import{_ as t,o as n,c as i,a5 as s}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Rich chat composer","description":"","frontmatter":{},"headers":[],"relativePath":"feature/chat-rich-composer/spec.md","filePath":"feature/chat-rich-composer/spec.md"}'),o={name:"feature/chat-rich-composer/spec.md"};function a(r,e,c,d,l,p){return n(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="rich-chat-composer" tabindex="-1">Rich chat composer <a class="header-anchor" href="#rich-chat-composer" aria-label="Permalink to &quot;Rich chat composer&quot;">​</a></h1><p>Scope confirmed 2026-10-24: basic formatting, links, lists, emoji and inline @mentions. No uploads, scheduling, audio/video messages. Existing permissions, thread/context, rate limits and retry identity remain unchanged.</p><p>Scheduling is added separately by <code>../chat-scheduled-messages/spec.md</code> (2026-10-26), including DM, channel and thread replies; the original composer scope above is historical.</p><p>WYSIWYG editor supports bold/italic/underline/strike, inline code, code block, blockquote, bullet/numbered lists and HTTP(S) links. Enter sends in every block; Shift+Enter inserts a line break. IME and mention selection must never send. In a list, Shift+Enter splits to the next item; on an empty item it exits the list to a normal paragraph. Shift+Enter in code inserts a code line. Keyboard guidance must reflect these list/code contexts. Per the 2026-10-27 UI request, keyboard guidance is screen-reader-only in every layout; it must not occupy space in the composer footer, including thread panels. Lists support nesting with Tab/Shift+Tab and indent/outdent toolbar controls. Outside lists, Tab keeps normal focus navigation. Invalid indent actions are disabled; nesting is bounded to five levels to preserve the JSON depth limit. Composer and sent messages share depth-based markers (1/a/i and disc/circle/square). Emoji are message content, not structural UI icons. Mentions are atomic chips.</p><p>Keep <code>content</code> plain text (max 4000) for existing clients/search/notifications. Optional <code>richContent</code> is an allowlisted JSON document, not arbitrary HTML. Plain messages without richContent remain unchanged. Reject unsafe links, unknown nodes, oversized/deep documents and inconsistent plain text/mention recipients. No backfill. If chat_messages has no validator, migration installs only the optional richContent constraint, not the full fresh-init required fields. Existing constraints and index definitions must never be replaced or weakened. Missing collection still blocks.</p><p>Toolbar/picker labels use parallel vi/en <code>chat.rich.*</code> keys and existing composer keys. Semantic theme tokens, keyboard accessible controls and 375/768/1440 layouts. Preserve local changes already present in chat UI; do not modify publish/editor.</p>',6)])])}const u=t(o,[["render",a]]);export{m as __pageData,u as default};
